"package com.example.app.iam.security;

import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

public record PortalSessionPrincipal(
        String sessionId,
        UUID userId,
        String workspaceEmail,
        String displayName,
        String department,
        List<String> roles,
        String effectiveViewAsRole,
        boolean readOnlyOverlay,
        Instant expiresAt) {

    public PortalSessionPrincipal {
        Objects.requireNonNull(sessionId, "sessionId must not be null");
        Objects.requireNonNull(userId, "userId must not be null");
        Objects.requireNonNull(workspaceEmail, "workspaceEmail must not be null");
        Objects.requireNonNull(displayName, "displayName must not be null");
        roles = roles == null ? List.of() : List.copyOf(roles);
        Objects.requireNonNull(expiresAt, "expiresAt must not be null");
    }

    @Override
    public List<String> roles() {
        return List.copyOf(roles);
    }
}
